import { useEffect, useMemo, useRef, useState } from "react";
import AMapLoader from "@amap/amap-jsapi-loader";
import {
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  Line,
  LineChart,
  Pie,
  PieChart,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from "recharts";
import { fetchAnalysis, fetchDataRange, fetchPublicConfig, fetchTraffic } from "./api/client";
import "./App.css";

const INTERVAL_OPTIONS = [
  { value: "auto", label: "自动" },
  { value: 10, label: "10 分钟" },
  { value: 20, label: "20 分钟" },
  { value: 30, label: "30 分钟" },
  { value: 60, label: "60 分钟" },
  { value: 120, label: "120 分钟" },
];
const DIRECTION_OPTIONS = ["全部方向", "东向西", "西向东", "南向北", "北向南"];
const PIE_COLORS = ["#4a8fff", "#20b486", "#f3bf48", "#7280ff", "#ff7a4d"];

function toApiTime(value) {
  return value ? value.replace("T", " ") : undefined;
}

function toInputTime(dateOrStr) {
  const date = new Date(dateOrStr);
  if (Number.isNaN(date.getTime())) return "";
  const pad = (v) => `${v}`.padStart(2, "0");
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}T${pad(
    date.getHours()
  )}:${pad(date.getMinutes())}`;
}

function formatBucket(ts) {
  const d = new Date(ts);
  const h = `${d.getHours()}`.padStart(2, "0");
  const m = `${d.getMinutes()}`.padStart(2, "0");
  return `${h}:${m}`;
}

function chooseAutoInterval(startInput, endInput) {
  const start = new Date(startInput).getTime();
  const end = new Date(endInput).getTime();
  const hours = (end - start) / 3600000;
  if (hours <= 3) return 10;
  if (hours <= 8) return 20;
  if (hours <= 16) return 30;
  if (hours <= 36) return 60;
  return 120;
}

function getRoadAvg(rows) {
  const grouped = new Map();
  rows.forEach((row) => {
    const current = grouped.get(row.site_name) || { sum: 0, n: 0 };
    current.sum += row.vehicle_count;
    current.n += 1;
    grouped.set(row.site_name, current);
  });
  const result = new Map();
  grouped.forEach((v, k) => result.set(k, v.n ? v.sum / v.n : 0));
  return result;
}

function levelColor(value) {
  if (value >= 60) return "#e04b2f";
  if (value >= 30) return "#f2be48";
  return "#2db983";
}

function segmentLength(vehicleCount) {
  if (vehicleCount >= 80) return 0.0012;
  if (vehicleCount >= 40) return 0.00085;
  return 0.00055;
}

function markerOffset(index) {
  const arr = [
    [0, 0],
    [10, -8],
    [-10, 8],
    [8, 10],
    [-8, -10],
  ];
  return arr[index % arr.length];
}

function buildDirectionData(rows, roadName) {
  if (!roadName) return [];
  const grouped = new Map();
  rows.filter((x) => x.site_name === roadName).forEach((row) => {
    grouped.set(row.approach, (grouped.get(row.approach) || 0) + row.vehicle_count);
  });
  return [...grouped.entries()].map(([name, value]) => ({ name, value }));
}

function getCardStats(rows, roadName) {
  const target = rows.filter((x) => x.site_name === roadName);
  if (!target.length) return { flow: 0, speed: 0, weather: "-" };
  const flow = target.reduce((s, x) => s + x.vehicle_count, 0) / target.length;
  const speed = target.reduce((s, x) => s + x.avg_speed, 0) / target.length;
  const weather = target[0].weather || "-";
  return { flow: Math.round(flow), speed: Number(speed.toFixed(1)), weather };
}

function App() {
  const [amapKey, setAmapKey] = useState("");
  const [intersections, setIntersections] = useState([]);
  const [selectedRoad, setSelectedRoad] = useState("");

  const [flowRoad, setFlowRoad] = useState("全部路口平均");
  const [speedRoad, setSpeedRoad] = useState("全部路口平均");
  const [direction, setDirection] = useState("全部方向");
  const [intervalMode, setIntervalMode] = useState("auto");

  const [startInput, setStartInput] = useState("");
  const [endInput, setEndInput] = useState("");
  const [timeLimit, setTimeLimit] = useState({ min: "", max: "" });
  const [applied, setApplied] = useState(null);

  const [flowData, setFlowData] = useState([]);
  const [speedData, setSpeedData] = useState([]);
  const [trafficRows, setTrafficRows] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const mapContainerRef = useRef(null);
  const mapRef = useRef(null);
  const AMapRef = useRef(null);
  const markersRef = useRef([]);
  const linesRef = useRef([]);

  const endMin = useMemo(() => {
    if (!startInput) return timeLimit.min;
    const s = new Date(startInput).getTime();
    return toInputTime(new Date(s + 3600000));
  }, [startInput, timeLimit.min]);

  const currentInterval = useMemo(() => {
    if (!applied) return 10;
    if (intervalMode === "auto") return chooseAutoInterval(applied.start, applied.end);
    return Number(intervalMode);
  }, [intervalMode, applied]);

  useEffect(() => {
    let active = true;
    async function bootstrap() {
      try {
        const [cfg, range] = await Promise.all([fetchPublicConfig(), fetchDataRange()]);
        if (!active) return;
        setAmapKey(cfg.amap_api_key);
        const sites = (cfg.intersections || []).filter((x) => x.longitude || x.latitude);
        setIntersections(sites);
        if (sites.length) setSelectedRoad(sites[0].site_name);

        const min = toInputTime(range.min_timestamp);
        const max = toInputTime(range.max_timestamp);
        const start = min;
        const candidateEnd = toInputTime(new Date(new Date(start).getTime() + 3600000));
        const end = candidateEnd > max ? max : candidateEnd;
        setTimeLimit({ min, max });
        setStartInput(start);
        setEndInput(end);
        setApplied({ start, end });
      } catch (err) {
        if (!active) return;
        setError(`初始化失败：${err.message}`);
      }
    }
    bootstrap();
    return () => {
      active = false;
    };
  }, []);

  useEffect(() => {
    if (!amapKey || !intersections.length || !mapContainerRef.current) return undefined;
    let destroyed = false;
    async function initMap() {
      try {
        const AMap = await AMapLoader.load({
          key: amapKey,
          version: "2.0",
          plugins: ["AMap.Scale", "AMap.ToolBar"],
        });
        if (destroyed) return;
        AMapRef.current = AMap;
        const center = [intersections[0].longitude, intersections[0].latitude];
        const map = new AMap.Map(mapContainerRef.current, {
          center,
          zoom: 15,
          viewMode: "2D",
        });
        map.addControl(new AMap.Scale());
        map.addControl(new AMap.ToolBar({ position: "LB" }));
        mapRef.current = map;

        markersRef.current = intersections.map((site, idx) => {
          const off = markerOffset(idx);
          const marker = new AMap.Marker({
            position: [site.longitude, site.latitude],
            offset: new AMap.Pixel(off[0], off[1]),
            content: '<div class="road-dot"></div>',
            label: {
              direction: "top",
              content: `<div class="amap-label">${site.site_name}</div>`,
              offset: new AMap.Pixel(off[0], off[1] - 8),
            },
          });
          marker.on("click", () => setSelectedRoad(site.site_name));
          marker.setMap(map);
          return marker;
        });
      } catch (err) {
        setError(
          `地图加载失败：${err.message}。请确认 Web JS API key 的白名单包含 localhost 与 127.0.0.1。`
        );
      }
    }
    initMap();
    return () => {
      destroyed = true;
      linesRef.current.forEach((x) => x.setMap(null));
      linesRef.current = [];
      if (mapRef.current) {
        mapRef.current.destroy();
        mapRef.current = null;
      }
    };
  }, [amapKey, intersections]);

  useEffect(() => {
    if (!applied) return;
    let active = true;
    async function loadData() {
      try {
        setLoading(true);
        setError("");
        const intervalMinutes = intervalMode === "auto" ? chooseAutoInterval(applied.start, applied.end) : Number(intervalMode);
        const common = {
          start_time: toApiTime(applied.start),
          end_time: toApiTime(applied.end),
          direction: direction === "全部方向" ? undefined : direction,
          interval_minutes: intervalMinutes,
        };
        const [flowResp, speedResp, trafficResp] = await Promise.all([
          fetchAnalysis({ ...common, road_name: flowRoad === "全部路口平均" ? undefined : flowRoad }),
          fetchAnalysis({ ...common, road_name: speedRoad === "全部路口平均" ? undefined : speedRoad }),
          fetchTraffic({ ...common, limit: 4000 }),
        ]);
        if (!active) return;
        setFlowData((flowResp || []).map((x) => ({ ...x, bucketLabel: formatBucket(x.bucket_start) })));
        setSpeedData((speedResp || []).map((x) => ({ ...x, bucketLabel: formatBucket(x.bucket_start) })));
        setTrafficRows(trafficResp || []);
      } catch (err) {
        if (!active) return;
        setError(`数据加载失败：${err.message}`);
      } finally {
        if (active) setLoading(false);
      }
    }
    loadData();
    return () => {
      active = false;
    };
  }, [applied, flowRoad, speedRoad, direction, intervalMode]);

  useEffect(() => {
    if (!mapRef.current || !selectedRoad) return;
    const road = intersections.find((x) => x.site_name === selectedRoad);
    if (road) mapRef.current.setCenter([road.longitude, road.latitude]);
  }, [selectedRoad, intersections]);

  const roadAvg = useMemo(() => getRoadAvg(trafficRows), [trafficRows]);
  useEffect(() => {
    if (!mapRef.current || !AMapRef.current) return;
    linesRef.current.forEach((x) => x.setMap(null));
    linesRef.current = [];
    intersections.forEach((site, idx) => {
      const avg = roadAvg.get(site.site_name) || 0;
      const len = segmentLength(avg);
      const axis = idx % 2 === 0 ? "lng" : "lat";
      const p1 =
        axis === "lng"
          ? [site.longitude - len / 2, site.latitude]
          : [site.longitude, site.latitude - len / 2];
      const p2 =
        axis === "lng"
          ? [site.longitude + len / 2, site.latitude]
          : [site.longitude, site.latitude + len / 2];
      const line = new AMapRef.current.Polyline({
        path: [p1, p2],
        strokeColor: levelColor(avg),
        strokeWeight: 8,
        strokeOpacity: 0.92,
        lineCap: "round",
      });
      line.setMap(mapRef.current);
      linesRef.current.push(line);
    });
  }, [roadAvg, intersections]);

  const roadOptions = useMemo(() => ["全部路口平均", ...intersections.map((x) => x.site_name)], [intersections]);
  const selectedCardStats = useMemo(() => getCardStats(trafficRows, selectedRoad), [trafficRows, selectedRoad]);
  const directionData = useMemo(() => buildDirectionData(trafficRows, selectedRoad), [trafficRows, selectedRoad]);

  function handleConfirm() {
    if (!startInput || !endInput) {
      setError("请先完整选择起止时间。");
      return;
    }
    const start = new Date(startInput).getTime();
    const end = new Date(endInput).getTime();
    if (end - start < 3600000) {
      setError("终止时间必须至少晚于起始时间 1 小时。");
      return;
    }
    setApplied({ start: startInput, end: endInput });
  }

  function handleResetView() {
    if (!mapRef.current || !intersections.length) return;
    mapRef.current.setCenter([intersections[0].longitude, intersections[0].latitude]);
    mapRef.current.setZoom(15);
  }

  return (
    <div className="app-shell">
      <div className="main-layout">
        <section className="left-map-panel">
          <div className="panel-title">实时流量地图</div>
          <div className="time-card">
            <label>起始时间</label>
            <input
              type="datetime-local"
              min={timeLimit.min}
              max={timeLimit.max}
              value={startInput}
              onChange={(e) => {
                const v = e.target.value;
                setStartInput(v);
                if (endInput && new Date(endInput).getTime() < new Date(v).getTime() + 3600000) {
                  setEndInput(toInputTime(new Date(new Date(v).getTime() + 3600000)));
                }
              }}
            />
            <label>终止时间</label>
            <input
              type="datetime-local"
              min={endMin}
              max={timeLimit.max}
              value={endInput}
              onChange={(e) => setEndInput(e.target.value)}
            />
            <button type="button" onClick={handleConfirm}>
              确定
            </button>
          </div>
          <button type="button" className="reset-view-btn" onClick={handleResetView}>
            默认视图
          </button>
          <div className="map-frame" ref={mapContainerRef} />

          {selectedRoad ? (
            <div className="road-popup">
              <div className="popup-head">
                <h3>{selectedRoad}</h3>
                <span>{selectedCardStats.weather}</span>
              </div>
              <div className="popup-metrics">
                <div>
                  <label>总车流量</label>
                  <strong>{selectedCardStats.flow}</strong>
                </div>
                <div>
                  <label>平均车速</label>
                  <strong>{selectedCardStats.speed} km/h</strong>
                </div>
              </div>
              <div className="popup-body">
                <ResponsiveContainer width="48%" height={140}>
                  <PieChart>
                    <Pie data={directionData} dataKey="value" nameKey="name" innerRadius={30} outerRadius={54}>
                      {directionData.map((item, idx) => (
                        <Cell key={item.name} fill={PIE_COLORS[idx % PIE_COLORS.length]} />
                      ))}
                    </Pie>
                    <Tooltip />
                  </PieChart>
                </ResponsiveContainer>
                <div className="dir-list">
                  {directionData.map((item, idx) => (
                    <div key={item.name} className="dir-item">
                      <span className="dir-dot" style={{ backgroundColor: PIE_COLORS[idx % PIE_COLORS.length] }} />
                      <span>{item.name}</span>
                      <strong>{item.value}</strong>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          ) : null}
        </section>

        <aside className="right-panel">
          <section className="section-block">
            <div className="section-head">
              <h2>数据分析展示</h2>
              <div className="granularity-box">
                <span>时间粒度</span>
                <select value={intervalMode} onChange={(e) => setIntervalMode(e.target.value)}>
                  {INTERVAL_OPTIONS.map((op) => (
                    <option key={op.value} value={op.value}>
                      {op.label}
                    </option>
                  ))}
                </select>
              </div>
            </div>
            <div className="toolbar-row">
              <select value={direction} onChange={(e) => setDirection(e.target.value)}>
                {DIRECTION_OPTIONS.map((x) => (
                  <option key={x} value={x}>
                    {x}
                  </option>
                ))}
              </select>
              <span className="range-text">
                {applied ? `${applied.start.replace("T", " ")} ~ ${applied.end.replace("T", " ")}` : "-"}
              </span>
            </div>

            <div className="chart-card">
              <div className="chart-head">
                <h3>车流量柱状图</h3>
                <select value={flowRoad} onChange={(e) => setFlowRoad(e.target.value)}>
                  {roadOptions.map((name) => (
                    <option key={name} value={name}>
                      {name}
                    </option>
                  ))}
                </select>
              </div>
              <ResponsiveContainer width="100%" height={250}>
                <BarChart data={flowData}>
                  <CartesianGrid strokeDasharray="3 3" />
                  <XAxis dataKey="bucketLabel" />
                  <YAxis />
                  <Tooltip />
                  <Bar dataKey="vehicle_count" fill="#3d87ff" radius={[5, 5, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
            </div>

            <div className="chart-card">
              <div className="chart-head">
                <h3>车速折线图</h3>
                <select value={speedRoad} onChange={(e) => setSpeedRoad(e.target.value)}>
                  {roadOptions.map((name) => (
                    <option key={name} value={name}>
                      {name}
                    </option>
                  ))}
                </select>
              </div>
              <ResponsiveContainer width="100%" height={250}>
                <LineChart data={speedData}>
                  <CartesianGrid strokeDasharray="3 3" />
                  <XAxis dataKey="bucketLabel" />
                  <YAxis />
                  <Tooltip />
                  <Line type="monotone" dataKey="avg_speed" stroke="#22b88f" strokeWidth={2.5} dot={false} />
                </LineChart>
              </ResponsiveContainer>
            </div>
          </section>

          <section className="section-block">
            <h2>预测</h2>
            <div className="dev-card">
              <div>开发中</div>
              <small>后续将接入预测模型与文字解释</small>
            </div>
          </section>
        </aside>
      </div>
      {loading ? <div className="floating-tip">数据更新中...</div> : null}
      {error ? <div className="floating-error">{error}</div> : null}
      <div className="effective-tip">当前有效粒度：{currentInterval} 分钟</div>
    </div>
  );
}

export default App;
